/**
 * app.js – LearnToken Sale DApp
 *
 * Covers:
 *  FE-12 – Wallet connection + automatic Sepolia network switch
 *  FE-13 – ETH balance display
 *  FE-14 – Buy tokens
 *  FE-15 – LRN token balance display
 *  FE-16 – Disable buy when MAX_SUPPLY reached
 *  FE-17 – Disable sell when contract has insufficient ETH
 *
 * Depends on:
 *  • ethers.js v6 (loaded via CDN in index.html)
 *  • config.js  (generated by deploy script – NETWORK_CONFIG, CONTRACT_ADDRESSES, TOKEN_CONFIG)
 *  • abi/LearnToken.json
 *  • abi/TokenSale.json
 */

"use strict";

// ═══════════════════════════════════════════════════════════════════════════════
// ABI (inlined so the DApp works without a build step even before first deploy)
// These will be overwritten by the deploy script via abi/*.json fetches.
// ═══════════════════════════════════════════════════════════════════════════════
const FALLBACK_TOKEN_ABI = [
  "function name() view returns (string)",
  "function symbol() view returns (string)",
  "function decimals() view returns (uint8)",
  "function totalSupply() view returns (uint256)",
  "function balanceOf(address) view returns (uint256)",
  "function approve(address,uint256) returns (bool)",
  "function allowance(address,address) view returns (uint256)",
  "function maxSupply() view returns (uint256)",
  "function cap() view returns (uint256)",
];

const FALLBACK_SALE_ABI = [
  "function buyTokens() payable",
  "function sellTokens(uint256) returns (bool)",
  "function buyPrice() view returns (uint256)",
  "function sellPrice() view returns (uint256)",
  "function ethBalance() view returns (uint256)",
  "function tokenReserve() view returns (uint256)",
  "event TokensPurchased(address indexed buyer, uint256 tokenAmount, uint256 ethPaid)",
  "event TokensSold(address indexed seller, uint256 tokenAmount, uint256 ethReceived)",
];

// ═══════════════════════════════════════════════════════════════════════════════
// State
// ═══════════════════════════════════════════════════════════════════════════════
const State = {
  provider: null,
  signer: null,
  account: null,
  tokenContract: null,
  saleContract: null,
  tokenAbi: FALLBACK_TOKEN_ABI,
  saleAbi: FALLBACK_SALE_ABI,
  decimals: 18,
  buyPrice: 0n,
  sellPrice: 0n,
  maxSupply: 0n,
  totalSupply: 0n,
  contractEth: 0n,
  userEth: 0n,
  userLrn: 0n,
  isCapped: false,
  pollTimer: null,
};

// ═══════════════════════════════════════════════════════════════════════════════
// DOM helpers
// ═══════════════════════════════════════════════════════════════════════════════
const el = (id) => document.getElementById(id);

function setText(id, txt) {
  const node = el(id);
  if (node) node.textContent = txt;
}

function setInnerHTML(id, html) {
  const node = el(id);
  if (node) node.innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Toast notifications
// ═══════════════════════════════════════════════════════════════════════════════
const TOAST_ICONS = { success: "✅", error: "❌", info: "ℹ️", warning: "⚠️" };

function toast(type, title, message, durationMs = 6000) {
  const container = el("toast-container");
  const t = document.createElement("div");
  t.className = `toast toast-${type}`;

  const iconDiv = document.createElement("div");
  iconDiv.className = "toast-icon";
  iconDiv.textContent = TOAST_ICONS[type] || "ℹ️";

  const bodyDiv = document.createElement("div");
  bodyDiv.className = "toast-body";

  const titleDiv = document.createElement("div");
  titleDiv.className = "toast-title";
  titleDiv.textContent = title;
  bodyDiv.appendChild(titleDiv);

  if (message) {
    const msgDiv = document.createElement("div");
    msgDiv.className = "toast-msg";
    msgDiv.textContent = message;
    bodyDiv.appendChild(msgDiv);
  }

  t.appendChild(iconDiv);
  t.appendChild(bodyDiv);
  container.appendChild(t);
  setTimeout(() => {
    t.classList.add("toast-out");
    t.addEventListener("animationend", () => t.remove());
  }, durationMs);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Format helpers
// ═══════════════════════════════════════════════════════════════════════════════
function fmtEth(wei, dp = 4) {
  const val = parseFloat(ethers.formatEther(wei));
  return val.toLocaleString("en-US", { minimumFractionDigits: dp, maximumFractionDigits: dp });
}

function fmtToken(wei, decimals = 18, dp = 2) {
  const val = parseFloat(ethers.formatUnits(wei, decimals));
  return val.toLocaleString("en-US", { minimumFractionDigits: dp, maximumFractionDigits: dp });
}

function shortAddr(addr) {
  return addr.slice(0, 6) + "…" + addr.slice(-4);
}

function explorerLink(hash, type = "tx") {
  const base = (typeof NETWORK_CONFIG !== "undefined")
    ? NETWORK_CONFIG.blockExplorer
    : "https://sepolia.etherscan.io";
  return `${base}/${type}/${hash}`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// ABI loading (from files generated by deploy, with fallback to human-readable)
// ═══════════════════════════════════════════════════════════════════════════════
async function loadAbis() {
  try {
    const [tokenResp, saleResp] = await Promise.all([
      fetch("abi/LearnToken.json"),
      fetch("abi/TokenSale.json"),
    ]);
    if (tokenResp.ok && saleResp.ok) {
      State.tokenAbi = await tokenResp.json();
      State.saleAbi  = await saleResp.json();
    }
  } catch {
    // fallback ABIs already set
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Network handling (FE-12)
// ═══════════════════════════════════════════════════════════════════════════════
const TARGET_CHAIN = (typeof NETWORK_CONFIG !== "undefined")
  ? NETWORK_CONFIG
  : {
      chainId: 11155111,
      chainIdHex: "0xaa36a7",
      name: "Sepolia",
      rpcUrl: "https://rpc.sepolia.org",
      blockExplorer: "https://sepolia.etherscan.io",
      nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
    };

async function ensureCorrectNetwork() {
  const chainId = await window.ethereum.request({ method: "eth_chainId" });
  if (chainId === TARGET_CHAIN.chainIdHex) return true;

  toast("info", "Switching network…", `Switching to ${TARGET_CHAIN.name}`);
  try {
    await window.ethereum.request({
      method: "wallet_switchEthereumChain",
      params: [{ chainId: TARGET_CHAIN.chainIdHex }],
    });
    return true;
  } catch (switchErr) {
    // Chain not added yet – add it
    if (switchErr.code === 4902) {
      try {
        await window.ethereum.request({
          method: "wallet_addEthereumChain",
          params: [{
            chainId: TARGET_CHAIN.chainIdHex,
            chainName: TARGET_CHAIN.name,
            rpcUrls: [TARGET_CHAIN.rpcUrl],
            blockExplorerUrls: [TARGET_CHAIN.blockExplorer],
            nativeCurrency: TARGET_CHAIN.nativeCurrency,
          }],
        });
        return true;
      } catch {
        toast("error", "Network error", "Could not add Sepolia to MetaMask.");
        return false;
      }
    }
    toast("error", "Network switch rejected", "Please switch to Sepolia manually.");
    return false;
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Contract initialisation
// ═══════════════════════════════════════════════════════════════════════════════
function initContracts() {
  const addrs = (typeof CONTRACT_ADDRESSES !== "undefined")
    ? CONTRACT_ADDRESSES
    : { learnToken: null, tokenSale: null };

  if (!addrs.learnToken || !addrs.tokenSale) {
    toast("warning", "Contracts not deployed", "Deploy the contracts first and re-open this page.");
    return false;
  }

  State.tokenContract = new ethers.Contract(addrs.learnToken, State.tokenAbi, State.signer);
  State.saleContract  = new ethers.Contract(addrs.tokenSale,  State.saleAbi,  State.signer);

  // Display addresses
  const exToken = explorerLink(addrs.learnToken, "address");
  const exSale  = explorerLink(addrs.tokenSale,  "address");
  setInnerHTML("addr-token", `<a href="${exToken}" target="_blank" rel="noopener">${shortAddr(addrs.learnToken)}</a>`);
  setInnerHTML("addr-sale",  `<a href="${exSale}"  target="_blank" rel="noopener">${shortAddr(addrs.tokenSale)}</a>`);

  return true;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Data polling
// ═══════════════════════════════════════════════════════════════════════════════
async function refreshData() {
  if (!State.account || !State.tokenContract) return;

  try {
    const [
      userEthRaw,
      userLrnRaw,
      totalSupplyRaw,
      maxSupplyRaw,
      contractEthRaw,
      reserveRaw,
      buyPriceRaw,
      sellPriceRaw,
      decimals,
    ] = await Promise.all([
      State.provider.getBalance(State.account),
      State.tokenContract.balanceOf(State.account),
      State.tokenContract.totalSupply(),
      State.tokenContract.maxSupply(),
      State.provider.getBalance(State.saleContract.target),
      State.saleContract.tokenReserve(),
      State.saleContract.buyPrice(),
      State.saleContract.sellPrice(),
      State.tokenContract.decimals(),
    ]);

    State.userEth     = userEthRaw;
    State.userLrn     = userLrnRaw;
    State.totalSupply = totalSupplyRaw;
    State.maxSupply   = maxSupplyRaw;
    State.contractEth = contractEthRaw;
    State.buyPrice    = buyPriceRaw;
    State.sellPrice   = sellPriceRaw;
    State.decimals    = Number(decimals);
    State.isCapped    = totalSupplyRaw >= maxSupplyRaw;

    renderUI();
  } catch (err) {
    console.warn("Data refresh error:", err);
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Render UI
// ═══════════════════════════════════════════════════════════════════════════════
function renderUI() {
  // ── Balances (FE-13, FE-15) ─────────────────────────────────────────────
  setText("eth-balance",   fmtEth(State.userEth) + " ETH");
  setText("lrn-balance",   fmtToken(State.userLrn, State.decimals) + " LRN");
  setText("contract-eth",  fmtEth(State.contractEth) + " ETH");
  setText("total-supply",  fmtToken(State.totalSupply, State.decimals) + " LRN");
  // token-reserve is updated asynchronously via updateReserveDisplay()

  // ── Supply progress (FE-16) ──────────────────────────────────────────────
  const pct = State.maxSupply > 0n
    ? Number((State.totalSupply * 10000n) / State.maxSupply) / 100
    : 0;
  const pctStr = pct.toFixed(2) + "%";
  setText("supply-pct", pctStr);
  const bar = el("progress-bar");
  const track = el("progress-track");
  if (bar) bar.style.width = pctStr;
  if (track) track.setAttribute("aria-valuenow", pct.toFixed(0));

  const cappedMsg = el("supply-capped-msg");
  if (cappedMsg) {
    cappedMsg.classList.toggle("visible", State.isCapped);
  }

  // ── Buy button state (FE-16) ─────────────────────────────────────────────
  const btnBuy = el("btn-buy");
  const buyReason = el("buy-disabled-reason");
  if (btnBuy) {
    if (State.isCapped) {
      btnBuy.disabled = true;
      if (buyReason) buyReason.textContent = "⚠ Max supply reached – buying is disabled.";
    } else {
      btnBuy.disabled = false; // explicitly enable so HTML's default disabled is cleared
      if (buyReason) buyReason.textContent = "";
    }
  }

  // ── Sell button state (FE-17) ────────────────────────────────────────────
  const btnSell = el("btn-sell");
  const sellReason = el("sell-disabled-reason");
  if (btnSell) {
    const sellAmt = parseSellAmount();
    // Only check ETH sufficiency if the user has entered an amount.
    // When no amount is entered, leave the button enabled so the user can type.
    if (sellAmt > 0n) {
      const ethNeeded = (sellAmt * State.sellPrice) / (10n ** BigInt(State.decimals));
      const hasEth = State.contractEth >= ethNeeded;
      btnSell.disabled = !hasEth;
      if (sellReason) {
        sellReason.textContent = hasEth ? "" : (
          State.contractEth === 0n
            ? "⚠ Contract has no ETH – buy tokens first to fund it."
            : "⚠ Insufficient contract ETH for this amount."
        );
      }
    } else {
      // No amount entered yet – enable the button
      btnSell.disabled = false;
      if (sellReason) sellReason.textContent = "";
    }
  }

  // Update estimate displays
  updateBuyEstimate();
  updateSellEstimate();
}

// ═══════════════════════════════════════════════════════════════════════════════
// Estimate helpers
// ═══════════════════════════════════════════════════════════════════════════════
function parseBuyAmount() {
  const raw = parseFloat(el("buy-amount")?.value || "0");
  if (!raw || raw <= 0) return 0n;
  return BigInt(Math.floor(raw)) * 10n ** BigInt(State.decimals);
}

function parseSellAmount() {
  const raw = parseFloat(el("sell-amount")?.value || "0");
  if (!raw || raw <= 0) return 0n;
  return BigInt(Math.floor(raw)) * 10n ** BigInt(State.decimals);
}

function updateBuyEstimate() {
  const amt = parseBuyAmount();
  const costNode = el("buy-eth-cost");
  if (!costNode) return;
  if (amt === 0n || State.buyPrice === 0n) {
    costNode.innerHTML = `Cost: <span>—</span>`;
    return;
  }
  const cost = (amt * State.buyPrice) / (10n ** BigInt(State.decimals));
  costNode.innerHTML = `Cost: <span>${fmtEth(cost, 6)} ETH</span>`;
}

function updateSellEstimate() {
  const amt = parseSellAmount();
  const recNode = el("sell-eth-receive");
  if (!recNode) return;
  if (amt === 0n || State.sellPrice === 0n) {
    recNode.innerHTML = `Receive: <span>—</span>`;
    return;
  }
  const receive = (amt * State.sellPrice) / (10n ** BigInt(State.decimals));
  recNode.innerHTML = `Receive: <span>${fmtEth(receive, 6)} ETH</span>`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Buy tokens (FE-14)
// ═══════════════════════════════════════════════════════════════════════════════
async function handleBuy() {
  const tokenAmt = parseBuyAmount();
  if (tokenAmt === 0n) {
    toast("warning", "Enter an amount", "Please enter the number of LRN tokens to buy.");
    return;
  }

  if (State.isCapped) {
    toast("error", "Max supply reached", "No more tokens can be minted.");
    return;
  }

  const ethCost = (tokenAmt * State.buyPrice) / (10n ** BigInt(State.decimals));

  if (ethCost > State.userEth) {
    toast("error", "Insufficient ETH", `You need ${fmtEth(ethCost, 6)} ETH but only have ${fmtEth(State.userEth, 6)} ETH.`);
    return;
  }

  const btnBuy = el("btn-buy");
  const origText = btnBuy.textContent;
  btnBuy.disabled = true;
  btnBuy.innerHTML = `<span class="spinner"></span>Confirming…`;

  try {
    toast("info", "Transaction pending", "Please confirm in MetaMask…");

    const tx = await State.saleContract.buyTokens({ value: ethCost });
    toast("info", "Transaction submitted", `<a class="tx-link" href="${explorerLink(tx.hash)}" target="_blank" rel="noopener">${shortAddr(tx.hash)}</a>`);

    await tx.wait();
    toast("success", "Tokens purchased! 🎉", `You received ${fmtToken(tokenAmt, State.decimals, 2)} LRN.`);
    el("buy-amount").value = "";
    await refreshData();
  } catch (err) {
    const msg = err.reason || err.message || "Transaction failed";
    toast("error", "Buy failed", msg.slice(0, 120));
  } finally {
    btnBuy.disabled = State.isCapped;
    btnBuy.textContent = origText;
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Sell tokens (FE-17)
// ═══════════════════════════════════════════════════════════════════════════════
async function handleSell() {
  const tokenAmt = parseSellAmount();
  if (tokenAmt === 0n) {
    toast("warning", "Enter an amount", "Please enter the number of LRN tokens to sell.");
    return;
  }

  if (tokenAmt > State.userLrn) {
    toast("error", "Insufficient LRN", `You only have ${fmtToken(State.userLrn, State.decimals, 2)} LRN.`);
    return;
  }

  const ethReceive = (tokenAmt * State.sellPrice) / (10n ** BigInt(State.decimals));
  if (State.contractEth < ethReceive) {
    toast("error", "Contract lacks ETH", "The contract doesn't have enough ETH to pay for this sale.");
    return;
  }

  const btnSell = el("btn-sell");
  const origText = btnSell.textContent;
  btnSell.disabled = true;
  btnSell.innerHTML = `<span class="spinner"></span>Approving…`;

  try {
    // Step 1: Approve
    toast("info", "Step 1/2", "Approving the sale contract to spend your LRN…");
    const saleAddress = State.saleContract.target;
    const currentAllowance = await State.tokenContract.allowance(State.account, saleAddress);

    if (currentAllowance < tokenAmt) {
      const approveTx = await State.tokenContract.approve(saleAddress, tokenAmt);
      toast("info", "Approval submitted", "Waiting for confirmation…");
      await approveTx.wait();
    }

    // Step 2: Sell
    btnSell.innerHTML = `<span class="spinner"></span>Selling…`;
    toast("info", "Step 2/2", "Submitting sell transaction…");

    const sellTx = await State.saleContract.sellTokens(tokenAmt);
    toast("info", "Transaction submitted", `<a class="tx-link" href="${explorerLink(sellTx.hash)}" target="_blank" rel="noopener">${shortAddr(sellTx.hash)}</a>`);

    await sellTx.wait();
    toast("success", "Tokens sold! 💰", `Received ${fmtEth(ethReceive, 6)} ETH.`);
    el("sell-amount").value = "";
    await refreshData();
  } catch (err) {
    const msg = err.reason || err.message || "Transaction failed";
    toast("error", "Sell failed", msg.slice(0, 120));
  } finally {
    btnSell.textContent = origText;
    // re-render to set correct disabled state
    renderUI();
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Connect Wallet (FE-12)
// ═══════════════════════════════════════════════════════════════════════════════
async function connectWallet() {
  if (!window.ethereum) {
    toast("error", "MetaMask not found", "Please install MetaMask and refresh.");
    return;
  }

  try {
    const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
    if (!accounts || accounts.length === 0) return;

    const ok = await ensureCorrectNetwork();
    if (!ok) return;

    State.provider = new ethers.BrowserProvider(window.ethereum);
    State.signer   = await State.provider.getSigner();
    State.account  = await State.signer.getAddress();

    // Load ABIs then init contracts
    await loadAbis();
    const contractsOk = initContracts();

    // Update header
    const btnConnect = el("btn-connect");
    btnConnect.textContent = shortAddr(State.account);
    btnConnect.classList.add("connected");

    el("network-dot").classList.add("connected");
    setText("network-name", TARGET_CHAIN.name);

    // Show/hide sections
    el("wallet-prompt").style.display  = "none";
    el("main-content").style.display   = "block";

    if (contractsOk) {
      await refreshData();
      await updateReserveDisplay();
      // Poll every 15s
      if (State.pollTimer) clearInterval(State.pollTimer);
      State.pollTimer = setInterval(async () => { await refreshData(); await updateReserveDisplay(); }, 15_000);
    }

    toast("success", "Wallet connected", shortAddr(State.account));
  } catch (err) {
    if (err.code === 4001) {
      toast("warning", "Connection rejected", "User rejected the connection request.");
    } else {
      toast("error", "Connection failed", err.message?.slice(0, 100));
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// MetaMask event listeners
// ═══════════════════════════════════════════════════════════════════════════════
function attachMetaMaskListeners() {
  if (!window.ethereum) return;

  window.ethereum.on("accountsChanged", async (accounts) => {
    if (accounts.length === 0) {
      // Disconnected
      State.account = null;
      el("wallet-prompt").style.display  = "block";
      el("main-content").style.display   = "none";
      el("btn-connect").textContent = "Connect Wallet";
      el("btn-connect").classList.remove("connected");
      el("network-dot").classList.remove("connected");
      setText("network-name", "Not connected");
      if (State.pollTimer) { clearInterval(State.pollTimer); State.pollTimer = null; }
      toast("info", "Wallet disconnected", "");
    } else {
      // Guard: re-initialise provider/signer if not yet set
      if (!State.provider) {
        State.provider = new ethers.BrowserProvider(window.ethereum);
      }
      State.account = accounts[0];
      State.signer  = await State.provider.getSigner();
      initContracts();
      await refreshData();
      el("btn-connect").textContent = shortAddr(State.account);
      toast("info", "Account switched", shortAddr(State.account));
    }
  });

  window.ethereum.on("chainChanged", () => {
    toast("info", "Network changed", "Reloading…");
    window.location.reload();
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Input event bindings
// ═══════════════════════════════════════════════════════════════════════════════
function attachInputListeners() {
  el("buy-amount")?.addEventListener("input", () => {
    updateBuyEstimate();
  });

  el("sell-amount")?.addEventListener("input", () => {
    updateSellEstimate();
    // Re-evaluate sell button disabled state live as user types
    if (State.account) {
      const sellAmt = parseSellAmount();
      const btnSell = el("btn-sell");
      const sellReason = el("sell-disabled-reason");
      if (btnSell) {
        if (sellAmt > 0n) {
          const ethNeeded = (sellAmt * State.sellPrice) / (10n ** BigInt(State.decimals));
          const hasEth = State.contractEth >= ethNeeded;
          btnSell.disabled = !hasEth;
          if (sellReason) {
            sellReason.textContent = hasEth ? "" : (
              State.contractEth === 0n
                ? "⚠ Contract has no ETH – buy tokens first to fund it."
                : "⚠ Insufficient contract ETH for this amount."
            );
          }
        } else {
          btnSell.disabled = false;
          if (sellReason) sellReason.textContent = "";
        }
      }
    }
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Initialise token reserve display (needs its own fetch after contracts ready)
// ═══════════════════════════════════════════════════════════════════════════════
async function updateReserveDisplay() {
  if (!State.saleContract) return;
  try {
    const reserve = await State.saleContract.tokenReserve();
    setText("token-reserve", fmtToken(reserve, State.decimals, 2) + " LRN");
  } catch {}
}

// ═══════════════════════════════════════════════════════════════════════════════
// Bootstrap
// ═══════════════════════════════════════════════════════════════════════════════
(function init() {
  // Wire connect button
  el("btn-connect").addEventListener("click", connectWallet);

  // Wire buy/sell buttons
  el("btn-buy")?.addEventListener("click", handleBuy);
  el("btn-sell")?.addEventListener("click", handleSell);

  // Wire input events
  attachInputListeners();

  // MetaMask events
  attachMetaMaskListeners();

  // Show placeholder prices from config if available
  if (typeof TOKEN_CONFIG !== "undefined") {
    try {
      State.buyPrice  = BigInt(TOKEN_CONFIG.buyPrice);
      State.sellPrice = BigInt(TOKEN_CONFIG.sellPrice);
      State.decimals  = TOKEN_CONFIG.decimals;
    } catch {}
  }

  // ── Enable buy/sell buttons once wallet is connected (they start disabled in HTML) ──
  // They will be properly managed by renderUI() after refreshData() resolves.
  // We do NOT pre-enable them here; renderUI() handles all button states.
})();
